            "    document.querySelector('#delivery-fee').disabled=!delivery;\n"
            "    document.querySelector('#address-field').classList.toggle('hidden',!delivery);\n"
            "    document.querySelector('#delivery-address').required=delivery;\n"
            '  }\n'
            '  function copyMeasurements(item){\n'
            '    const c=customer();if(!c)return;\n'
            '    const values=JSON.parse(c.measurements);\n'
            "    const suffixes=['unit','length','shoulder','bust','waist','hip','sleeve','arm','cuff'];\n"
            '    suffixes.forEach(key=>{const '
            'input=item.querySelector(`[name$="_${key}"]`);if(input)input.value=values[key]||(key===\'unit\'?\'inch\':\'\');});\n'
            '  }\n'
            '  function addItem(){\n'
            '    if(items.children.length>=30)return;\n'
            '    const '
            "fragment=document.querySelector('#item-template').content.cloneNode(true);items.append(fragment);\n"
            '    renumber();const item=items.lastElementChild;copyMeasurements(item);\n'
            "    const input=item.querySelector('.model-input');let timer,version=0;\n"
            '    async function lookup(){\n'
            '      const '
            "current=++version,code=input.value.trim(),message=item.querySelector('.model-result'),img=item.querySelector('img'),placeholder=item.querySelector('.photo-placeholder');\n"
            '      '
            "img.removeAttribute('src');img.classList.add('hidden');placeholder.classList.remove('hidden');input.setCustomValidity(say('اختر "
            "رقم موديل صحيحاً','Choose a valid model code'));\n"
            "      if(!code){message.textContent=say('اكتب رقم الموديل','Enter model code');return;}\n"
            "      message.textContent=say('جارٍ عرض الموديل…','Loading model…');\n"
            '      try{\n'
            '        const response=await '
            "fetch(`/api/model?code=${encodeURIComponent(code)}`,{headers:{Accept:'application/json'}});\n"
            '        if(current!==version)return;\n'
            "        if(!response.ok)throw new Error('not-found');\n"
            '        const model=await response.json();if(current!==version)return;\n'
            "        input.setCustomValidity('');message.classList.remove('error');message.textContent=model.title;\n"
            "        item.querySelector('.price-input').value=(model.price/100).toFixed(2);\n"
            '        '
            "if(model.photo_url){img.src=model.photo_url;img.classList.remove('hidden');placeholder.classList.add('hidden');}\n"
            '        totals();\n'
            "      }catch(error){if(current===version){message.textContent=say('لم يُعثر على الموديل. أضفه في الكتالوج "
            "أو تحقق من الاتصال.','Model not found. Add it to the catalogue or check your "
            "connection.');message.classList.add('error');item.querySelector('.price-input').value='';totals();}}\n"
            '    }\n'
            "    input.addEventListener('input',()=>{version++;clearTimeout(timer);input.setCustomValidity(say('انتظر "
